from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Bts_connection_status(EmssimCommand):
    def __init__(self, method="bts_connection_status", timeout=60, rpc_connection_name='localRPC'):
        super(Bts_connection_status, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Bts_connection_status, self).on_new_data(**data)
        if "msg" in data:
            if (data["msg"] == "connection_status"):
                self._ret['discover_status'] = 0
                self._ret['connection_status'] = 0
                self._ret['tcp_connection_status'] = 0
                try:
                    self._ret['discover_status'] = int(data['discover_status'])
                    self._ret['connection_status'] = int(data['connection_status'])
                    self._ret['tcp_connection_status'] = int(data['tcp_connection_status'])
                except Exception:
                    pass
        elif ("status" in data):
            self._ret["status"] = data["status"]
